
'use strict';
/* STATIC ROOM 003: source shelf and bounded local capability projection. */
const K='static-room-003-v3';
const PREVIOUS_K='static-room-002-v2';
const LEGACY_K='static-room-001-v1';
const START_NODES={
 song:{id:'song',name:'The House Takes Attendance',kind:'Song',glyph:'♫',address:'static://song/house-takes-attendance',summary:'A song as a doorway to scenes, images, arrangements, and remembered encounters.',source:'Demonstration seed · replace with a verified source',relations:[{to:'porch',type:'could become a scene',status:'proposed',why:'Shared porch and home imagery; creative proposal only.'},{to:'orchard',type:'shares a setting',status:'proposed',why:'Motif association in this demonstration seed.'},{to:'lyrics',type:'has working text',status:'established',why:'Bundled demonstration draft, not a verified transcript.'}]},
 porch:{id:'porch',name:'Porch at the edge of evening',kind:'Scene',glyph:'◧',address:'static://scene/porch-evening',summary:'A film scene shaped by sound, light, and arrival.',source:'Demonstration scene proposal',relations:[{to:'song',type:'may use as soundtrack',status:'proposed',why:'Creative association; no music files are bundled.'},{to:'pantry',type:'needs imagery',status:'fogged',why:'No actual photographs imported yet.'},{to:'cup',type:'contains a possible prop',status:'proposed',why:'Blue cup motif may fit the scene.'}]},
 orchard:{id:'orchard',name:'Orchard World',kind:'World',glyph:'✿',address:'static://world/orchard',summary:'A world that can hold characters, songs, scenes, places, and changing relationships.',source:'Demonstration world sketch',relations:[{to:'porch',type:'contains a possible place',status:'proposed',why:'Placement is not canonically established.'},{to:'cup',type:'contains an object',status:'proposed',why:'Proposed object relation; needs a project-source check.'},{to:'grace',type:'might host an experience',status:'fogged',why:'Scope and current implementation not verified here.'}]},
 lyrics:{id:'lyrics',name:'Working lyric leaf',kind:'Text',glyph:'≋',address:'static://text/house-lyrics',summary:'A deliberately blank working text surface; add your own words or source transcript.',source:'Demonstration placeholder',relations:[{to:'song',type:'working text for',status:'established',why:'Local prototype seed linkage.'}]},
 pantry:{id:'pantry',name:'Photo pantry',kind:'Collection',glyph:'▧',address:'static://collection/photo-pantry',summary:'A placeholder collection for imported photo references and future visual candidates.',source:'Demonstration collection · no real images imported',relations:[{to:'porch',type:'may supply imagery',status:'fogged',why:'The pantry has no connected photo archive or imported images.'}]},
 cup:{id:'cup',name:'Blue cup',kind:'World object',glyph:'◕',address:'static://object/blue-cup',summary:'A small object that could connect scene, gesture, world memory, and interaction.',source:'Demonstration world-object sketch',relations:[{to:'porch',type:'may appear in scene',status:'proposed',why:'Suggested creative composition.'},{to:'orchard',type:'may belong to world',status:'proposed',why:'Source world relation not verified.'}]},
 grace:{id:'grace',name:'Grace game seed',kind:'Experience',glyph:'♧',address:'static://experience/grace-game',summary:'A creative encounter seed whose real project state should be linked before use.',source:'Demonstration pointer · real project not loaded',relations:[{to:'orchard',type:'may share a world',status:'fogged',why:'Needs explicit source lineage and project-state inspection.'}]}
};
const BUNDLED_SOURCE_NODES={"source-workbench":{"id":"source-workbench","name":"Static Workbench · README witness","kind":"Project source","glyph":"⌘","address":"static://source/static-workbench/readme","summary":"Frozen excerpt from the Workbench README: local browser desk, bounded source handoff, descriptor-only future adapters. Not a live project connection.","source":"Bundled pinned source excerpt · GitHub read in preparation of Room 003","relations":[{"to":"song","type":"could support creative handoff","status":"proposed","why":"Project README describes source-handoff capability; relationship to demo song is an experiment, not documented project canon."}]},"source-fogglass":{"id":"source-fogglass","name":"FogGlass · README witness","kind":"Project source","glyph":"◌","address":"static://source/fogglass/readme","summary":"Frozen source excerpt from FogGlass defining fog addresses, lamps, lenses, receipts, and the distinction between observation and verdict.","source":"Bundled pinned source excerpt · GitHub read in preparation of Room 003","relations":[{"to":"orchard","type":"could expose unresolved world connections","status":"proposed","why":"Experimental application of FogGlass ideas to demo world; not a project-owned integration."}]},"source-fullmeasure":{"id":"source-fullmeasure","name":"Full Measure · World Layer witness","kind":"Project source","glyph":"✿","address":"static://source/full-measure/readme","summary":"Frozen README excerpt from the project-owned world layer, describing human-confirmed participation, witnessed steps, and model proposal boundaries.","source":"Bundled pinned source excerpt · GitHub read in preparation of Room 003","relations":[{"to":"grace","type":"might inform an experience","status":"fogged","why":"The project describes an executable world layer; specific Grace-game integration is not established by this excerpt."}]},"source-staticos":{"id":"source-staticos","name":"STATIC OS · Genesis witness","kind":"Project source","glyph":"▧","address":"static://source/static-os/readme","summary":"Frozen source excerpt identifying the STATIC OS bootstrap and separating image construction from actual boot proof.","source":"Bundled pinned source excerpt · GitHub read in preparation of Room 003","relations":[{"to":"source-workbench","type":"proposes a future host for","status":"proposed","why":"Architecture exploration; Room does not claim an installed or booted OS."}]}};
const BUNDLED_SOURCE_PROOFS={"source-workbench":{"repository":"the-static-collective/static-workbench","commit":"38d8840c053d3675818ac3b8b74ab56731434bd7","path":"README.md","blobSha":"36dfae809b883cd32219d85171f01c8610acceeb","checkedAt":"2026-09-24","lineStart":1,"url":"https://github.com/the-static-collective/static-workbench/blob/38d8840c053d3675818ac3b8b74ab56731434bd7/README.md","excerpt":"# Static Workbench\n\nA local-first browser workbench for a dedicated Static Collective Linux machine.\n\n**v0.2 remains intentionally read-only against project state.** It exposes the host, configured filesystem roots, Git repository state, a durable Workbench witness journal, and a deterministic HumanTerminal/APERTURE specimen that writes only Workbench-owned local semantic receipts. It does **not** yet execute or mutate Toaster, Dogram, ALEX, 3rdi, LOADOUT, or Static Live.\n\nThe browser is the desk. The supervisor is the local process boundary. Project-native identities and receipts remain owned by their projects."},"source-fogglass":{"repository":"the-static-collective/fogGlass","commit":"bff0ff0910061af12919a2778f72c85ff721c67d","path":"README.md","blobSha":"bc9690c9e0562bdd65bf07e36fe6fc42d8db28a0","checkedAt":"2026-09-24","lineStart":1,"url":"https://github.com/the-static-collective/fogGlass/blob/bff0ff0910061af12919a2778f72c85ff721c67d/README.md","excerpt":"# FOG-GLASSES-001\n\nA tiny, local, browser-executable instrument for inspecting uncertainty without collapsing it into a verdict.\n\n## Core law\n\n> The glasses may change what you can distinguish. They may not change the world to make it easier to see.\n\n## What it preserves\n\n- Fog is not a topological wall. A route may still exist while visibility degrades locally.\n- Fog has an address.\n- Fog has composition, grain, depth, motion, persistence, response, and unresolved origin."},"source-fullmeasure":{"repository":"the-static-collective/full-measure-world-layer","commit":"412081481d763b4adcc02f3a8b8eef02070fb000","path":"README.md","blobSha":"cdb1128473f403fa2638d819753f66f66806a04d","checkedAt":"2026-09-24","lineStart":1,"url":"https://github.com/the-static-collective/full-measure-world-layer/blob/412081481d763b4adcc02f3a8b8eef02070fb000/README.md","excerpt":"# Full Measure — World Layer\n\nFull Measure is the D&D-style life layer for real participation: a world people can inhabit, play through, and help shape without turning human worth into points.\n\nThe original Garden vertical still places evidence-derived participation over Jubilee Campfire's causal loop:\n\n```text\nTension → Pledge → Accept → Report → Human Witness → Harvest → Capacity\n```\n\nThe repository now also contains the executable **Boot the House v0.1** world-encounter loop, the **Human Terminal v0.1** basic-human operator membrane, and **STRIDE Specimen 001** for two separately confirmed local steps. These surfaces compose around the same authority boundary rather than creating parallel constitutions."},"source-staticos":{"repository":"the-static-collective/static-os","commit":"8bdb6ec5c258c1c98a777d3a83537569f4977a54","path":"README.md","blobSha":"f9764ae41680a30ab070057806cb0d9af3c4e51b","checkedAt":"2026-09-24","lineStart":1,"url":"https://github.com/the-static-collective/static-os/blob/8bdb6ec5c258c1c98a777d3a83537569f4977a54/README.md","excerpt":"# STATIC OS\n\nA project-owned, Linux-based computational habitat for the Static Collective.\n\n**Status:** GENESIS 001 / bootstrap under review. This repository does not yet contain a verified bootable ISO or installed OS.\n\nThe distribution integrates independently governed organs without absorbing their identity or authority. Debian supplies the kernel, boot, packages, and hardware support; STATIC OS owns its image composition, HOUSE session entry, provenance manifest, test gates, and operator documentation."}};
START_NODES.grace.relations.push({to:'source-fullmeasure',type:'possible project source',status:'fogged',why:'Full Measure README is a real frozen witness, but the specific Grace-game source relationship is unverified.'});
const INTENTS={explore:{label:'Explore relations',glyph:'◇',description:'Navigate the live neighborhood and preserve the state of each relationship.',modules:['relations','trace']},scene:{label:'Make a scene',glyph:'▣',description:'Project a scene-building desk around the current object.',modules:['scene','source','trace']},music:{label:'Arrange music',glyph:'♫',description:'Project a music arrangement desk without inventing an audio file.',modules:['music','source','trace']},story:{label:'Write a story',glyph:'✎',description:'Project a story desk, with a working manuscript and its source coordinates.',modules:['story','source','trace']},research:{label:'Investigate fog',glyph:'◌',description:'Project a question desk for uncertain relations, evidence, and next tests.',modules:['questions','relations','trace']},world:{label:'Grow a world',glyph:'✿',description:'Project a world-building desk for places, objects, affordances, and relations.',modules:['world','relations','trace']}};
const MODULES=['relations','scene','music','story','world','questions','source','trace','sourceReader','handoff'];
const CAPABILITIES={ 'source.excerpt':{label:'Inspect source excerpt',effects:['read bundled excerpt or imported local file'],permission:'Explicit user click',external:false},'brief.compose':{label:'Compose creative brief',effects:['write an independent local brief'],permission:'Explicit user click',external:false},'handoff.export':{label:'Export bounded handoff',effects:['download local JSON handoff'],permission:'Explicit user click',external:false}};
const MODULE_LABELS={relations:'Relation navigator',scene:'Scene desk',music:'Music desk',story:'Story desk',world:'World desk',questions:'Fog research',source:'Source ledger',trace:'Encounter notes',sourceReader:'Source reader',handoff:'Project handoff'};
const clone=x=>JSON.parse(JSON.stringify(x));
function defaultState(){return {version:3,sourceFiles:{},briefs:{},current:'song',intent:'explore',view:'room',fog:true,notes:{},drafts:{},questions:{},records:[],encounters:[],customNodes:{},relationDecisions:{},extraRelations:{},sequence:0,visited:['song'],stack:['song'],stackIndex:0,sessionName:'Front Room · local encounter',modulePicks:{},forgeSeed:null};}
function normalizeState(raw){
 const d=defaultState();
 if(!raw || ![1,2,3].includes(raw.version))throw Error('Unsupported Room snapshot version');
 for(const k of Object.keys(d)){
  if(k==='version')continue;
  if(Object.prototype.hasOwnProperty.call(raw,k)&&raw[k]!==null&&typeof raw[k]===typeof d[k])d[k]=clone(raw[k]);
 }
 const nn={...START_NODES,...BUNDLED_SOURCE_NODES,...d.customNodes};
 for(const key of Object.keys(d.customNodes))if(START_NODES[key]||BUNDLED_SOURCE_NODES[key])delete d.customNodes[key];
 if(!nn[d.current])d.current='song';
 if(!INTENTS[d.intent])d.intent='explore';
 if(!['room','field','history','receipt','forge','capsule','sources'].includes(d.view))d.view='room';
 if(!Array.isArray(d.records)||!Array.isArray(d.encounters)||!Array.isArray(d.stack)||!Array.isArray(d.visited))throw Error('Malformed Room history');
 if(Object.keys(d.customNodes).length>200||d.records.length>3000||d.encounters.length>1500)throw Error('Room snapshot exceeds local bounds');
 for(const [key,entry] of Object.entries(d.modulePicks)){
  if(!Array.isArray(entry)||entry.some(m=>!MODULES.includes(m)))delete d.modulePicks[key];
 }
 d.stack=d.stack.filter(x=>nn[x]); d.stackIndex=Math.min(Math.max(0,Number(d.stackIndex)||0),Math.max(0,d.stack.length-1));
 if(!d.stack.length){d.stack=[d.current];d.stackIndex=0;}
 d.version=3;return d;
}
function safeLoad(){
 try{const raw=localStorage.getItem(K)||localStorage.getItem(PREVIOUS_K)||localStorage.getItem(LEGACY_K);return raw?normalizeState(JSON.parse(raw)):defaultState();}
 catch{return defaultState();}
}
let state=defaultState();let storageOK=true;
try{localStorage.setItem('__static_room_probe','1');localStorage.removeItem('__static_room_probe');}catch{storageOK=false;}
state=safeLoad();
function nodes(){return {...START_NODES,...BUNDLED_SOURCE_NODES,...state.customNodes};}
function node(){return nodes()[state.current]||START_NODES.song;}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function persist(){if(!storageOK)return;try{localStorage.setItem(K,JSON.stringify(state));}catch{storageOK=false;notice('Browser storage is unavailable or full. Export a snapshot to keep your changes.');}}
function stamp(){return new Date().toISOString();}
function id(){state.sequence++;return String(state.sequence).padStart(4,'0');}
function record(type,detail){state.records.unshift({id:id(),at:stamp(),type,object:state.current,address:node().address,detail});state.records=state.records.slice(0,200);}
function notice(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.remove('hidden');clearTimeout(notice.t);notice.t=setTimeout(()=>e.classList.add('hidden'),3500);}
function setIntent(i,origin='explicit selection'){if(!INTENTS[i])return;state.intent=i;state.view='room';record('projection',`${INTENTS[i].label}; origin: ${origin}; modules: ${INTENTS[i].modules.join(', ')}`);persist();render();}
function go(to,push=true){if(!nodes()[to]){notice('That local object address is not registered.');return;}state.current=to;state.view='room';if(push){state.stack=state.stack.slice(0,state.stackIndex+1);state.stack.push(to);state.stackIndex=state.stack.length-1;}if(!state.visited.includes(to))state.visited.push(to);record('navigation',`Opened ${nodes()[to].address}`);persist();render();}
function routeAddress(raw){const val=raw.trim();if(!val)return;const found=Object.values(nodes()).find(n=>n.address.toLowerCase()===val.toLowerCase());if(found){go(found.id);return;}if(['static://room/front','static://room/home'].includes(val)){state.view='room';state.current='song';persist();render();return;}const m=val.match(/^static:\/\/make\/(.+)$/i);if(m){compose(m[1].replace(/[-_]/g,' '));return;}const s=val.match(/^static:\/\/session\/(\d+)$/i);if(s){const e=state.encounters.find(e=>e.id===s[1]);if(e){go(e.object);setIntent(e.intent,'encounter re-entry');return;}}notice('No registered local address. Try the object list or static://make/a-film-from-this-song.');}
function interpret(query){const q=query.toLowerCase();if(/fog|uncertain|unknown|question|investigat|verify|evidence/.test(q))return 'research';if(/song|music|arrang|sound|audio|play/.test(q)&&!/film|video|scene/.test(q))return 'music';if(/film|video|scene|shot|cinema/.test(q))return 'scene';if(/story|write|script|narrativ|chapter|lyric/.test(q))return 'story';if(/world|orchard|place|game|character/.test(q))return 'world';return 'explore';}
function compose(q){if(!q.trim())return;const i=interpret(q);state.notes['last-request']=q;setIntent(i,`local keyword rule from request: “${q.slice(0,140)}”`);notice(`Local projector selected “${INTENTS[i].label}”. No AI was called.`);}
function activeModules(){const k=state.current+'|'+state.intent;return state.modulePicks[k]||INTENTS[state.intent].modules;}
function badge(status){return `<span class="status ${esc(status)}">${esc(status)}</span>`;}
function allRelations(){return [...(node().relations||[]),...(state.extraRelations[state.current]||[])].map((r,k)=>({...r,key:`${state.current}:${k}`,status:state.relationDecisions[`${state.current}:${k}`]||r.status}));}
function hero(){const n=node();return `<section class="hero"><div><span class="eyebrow" style="color:#e6cb98">CURRENT ENCOUNTER / ${esc(n.kind.toUpperCase())}</span><h1>${esc(n.name)}</h1><p>${esc(n.summary)}</p></div><div class="hero-footer"><span class="tag">⌁ ${esc(n.address)}</span><span class="tag">◌ ${allRelations().length} neighboring doors</span><span class="tag">✳ ${esc(INTENTS[state.intent].label)}</span></div></section>`;}
function moduleMarkup(type){const n=node();const val=state.drafts[`${n.id}:${type}`]||'';
 if(type==='sourceReader')return sourceReaderMarkup(n);
 if(type==='handoff')return handoffModuleMarkup(n);const common={scene:['Scene desk','Describe the opening frame, camera movement, sound, and what changes.','Write a scene beat, image direction, or cinematic move…'],music:['Arrangement desk','Write tempo, instrumentation, dynamics, or a musical change. This demo contains no audio player or audio data.','What does this arrangement need?'],story:['Story desk','Create a narrative beat or draft paragraph; keep source text and speculation distinct.','Write the next passage or story beat…'],world:['World desk','Give this place or object an interaction, consequence, or new reachable relation.','A visitor can…'],questions:['Uncertainty desk','State what is known, what is proposed, and which encounter would actually test it.','Known / inferred / unknown / next test…'],trace:['Encounter notebook','A durable local working note. Record an observation without silently promoting it to a source fact.','What did you notice?'],source:['Source & lineage','This specimen may include demo seeds and local authoring. Attach a source coordinate or note what must be checked before promotion.','Exact source path, URL, commit, or unresolved source need…']}[type];
 if(type==='relations')return `<div class="module"><h4>◇ Relation navigator</h4><p>Established, proposed, and fogged doors remain distinct. Opening a door does not approve its claim.</p><div class="module-actions"><button class="action secondary small" data-viewgo="field">View full field map ↗</button></div></div>`;
 return `<div class="module"><h4>${esc(common[0])}</h4><p>${esc(common[1])}</p><label class="sr" for="draft-${type}">${esc(common[0])}</label><textarea id="draft-${type}" data-draft="${type}" placeholder="${esc(common[2])}">${esc(val)}</textarea><div class="module-actions"><button class="action secondary small" data-save="${type}">Save local trace</button><button class="action secondary small" data-export-md="${type}">Export .md ↗</button></div></div>`;}
function rackMarkup(){return `<details class="rack"><summary>⌘ Instrument rack · ${activeModules().length} mounted</summary><p class="subtle">Change the tools in this projection. This changes only the local workspace, not any source or external application.</p><div class="rack-grid">${MODULES.map(m=>`<label class="rack-choice"><input type="checkbox" data-module-control="${m}" ${activeModules().includes(m)?'checked':''}><span>${esc(MODULE_LABELS[m])}</span></label>`).join('')}</div></details>`;}
function doorsMarkup(){const rr=allRelations();return rr.length?rr.map(r=>{const t=nodes()[r.to];return `<button class="door" data-go="${esc(r.to)}"><span class="glyph">${esc(t?.glyph||'◇')}</span><span style="flex:1;min-width:0"><strong>${esc(t?.name||r.to)}</strong><small>${esc(r.type)} · ${esc(r.why)}</small></span>${badge(r.status)}</button>`;}).join(''):'<p class="empty">No edges in this demonstration seed yet. The notebook still works.</p>';}
function roomMarkup(){return `${hero()}<div class="row"><h2 class="heading">What shall we project?</h2><span class="subtle">A local compositional kernel</span></div><div class="tools">${Object.entries(INTENTS).map(([k,v])=>`<button class="tool ${state.intent===k?'selected':''}" data-intent="${k}" aria-pressed="${state.intent===k}"><span class="glyph">${esc(v.glyph)}</span><b>${esc(v.label)}</b><small>${esc(v.description)}</small></button>`).join('')}</div><section class="workspace"><div class="workspace-top"><div><span class="eyebrow">PROJECTED DESK · ${esc(node().kind.toUpperCase())}</span><h3>${esc(INTENTS[state.intent].label)}</h3><div class="subtle">${esc(INTENTS[state.intent].description)}</div></div><div class="module-actions"><button class="action secondary small" id="new-object">+ New object</button><button class="action secondary small" id="grow-draft">Grow draft ↗</button><button class="action secondary small" id="open-capsule">Context capsule ↗</button><button class="action" id="capture">Capture encounter ↗</button></div></div>${sourceQuickMarkup()}${rackMarkup()}<div class="split">${(BUNDLED_SOURCE_PROOFS[node().id]||state.sourceFiles[node().id]?['sourceReader','handoff',...activeModules().filter(m=>!['sourceReader','handoff'].includes(m))]:activeModules()).map(moduleMarkup).join('')}</div><p class="hint">Projection is deterministic and local. Module selection is explicit. Drafts are not source evidence until supported by a real source.</p></section><div class="row"><h2 class="heading">Reachable doors</h2><button class="action secondary small" data-viewgo="field">Field map ↗</button></div><div class="doorlist">${doorsMarkup()}</div>`;}
function fieldMarkup(){return `<div class="row"><div><span class="eyebrow">RELATIONAL NAVIGATION</span><h2 class="heading" style="margin-top:7px">The nearby field</h2></div><button class="action secondary small" id="toggle-fog">FogGlass ${state.fog?'ON':'OFF'}</button></div><p class="subtle">This prototype shows source-aware relationships between demonstration objects, not verified project facts. Toggle FogGlass to hide or show uncertainty annotations; the underlying relationships remain preserved.</p><section class="workspace"><span class="eyebrow">CURRENT OBJECT</span><h3>${esc(node().name)}</h3><p class="subtle">${esc(node().source)}</p><div class="flow-chips">${Object.values(nodes()).map(n=>`<button class="field-chip" data-go="${esc(n.id)}" ${n.id===state.current?'style="border-color:var(--gold);color:var(--gold)"':''}>${esc(n.glyph)} ${esc(n.name)}</button>`).join('')}</div></section><h2 class="heading">Edges from here</h2><div class="doorlist">${allRelations().map(r=>{const dest=nodes()[r.to];return `<article class="module"><div class="row"><h4 style="margin:0">${esc(node().name)} → ${esc(dest?.name||r.to)}</h4>${badge(r.status)}</div><p>${esc(r.type)}</p>${state.fog?`<div class="notification">${esc(r.why)}<br><br>Inspection does not constitute the relation.</div>`:''}<div class="module-actions"><button class="action secondary small" data-go="${esc(r.to)}">Open destination ↗</button>${r.status!=='established'?`<button class="action secondary small" data-question="${esc(r.key)}">Record question</button>`:''}</div></article>`;}).join('')||'<p class="empty">No edges.</p>'}</div><h2 class="heading">Create a relationship</h2>${relationFormMarkup()}<h2 class="heading">Research questions</h2>${Object.entries(state.questions).filter(([key])=>key.startsWith(state.current+':')).map(([key,q])=>`<div class="module" style="margin:9px 0"><h4>${esc(key)}</h4><p>${esc(q)}</p></div>`).join('')||'<p class="empty">No local questions recorded for this object.</p>'}`;}
const KINDS=['Song','Scene','World','Text','Collection','World object','Experience','Idea','Research','Image reference','Tool','Other'];
function forgeMarkup(){const seed=state.forgeSeed||{};const parent=nodes()[seed.from||state.current];return `<section class="hero"><div><span class="eyebrow">FIELD FORGE / LOCAL AUTHORSHIP</span><h1>Give an idea an address.</h1><p>Create a new object in the field. Its ancestry and the decision to connect it remain explicit.</p></div></section><section class="workspace"><h3>New creative object</h3><form id="forge-form" class="author-form"><label>Name<input name="name" maxlength="120" required placeholder="The bell on the hill" value="${esc(seed.name||'')}"></label><label>Kind<select name="kind">${KINDS.map(k=>`<option ${k===(seed.kind||'Idea')?'selected':''}>${esc(k)}</option>`).join('')}</select></label><label>What is it?<textarea name="summary" maxlength="2000" placeholder="One or two sentences about this object…">${esc(seed.summary||'')}</textarea></label><label>Source coordinate / ancestry (optional)<input name="source" maxlength="1000" placeholder="Exact path, URL, original encounter or local author…" value="${esc(seed.source||'')}"></label><label>Door from ${esc(parent.name)}<input name="relation" maxlength="160" value="${esc(seed.relation||'inspired a new local object')}"></label>${seed.content?`<div class="notification">The current draft will be copied into the new object's working notes. Its original remains unchanged.</div>`:''}<div class="module-actions"><button class="action" type="submit">Create object + proposed door ↗</button><button type="button" class="action secondary" id="cancel-forge">Cancel</button></div></form></section>`;}
function relationFormMarkup(){const choices=Object.values(nodes()).filter(n=>n.id!==state.current);return `<form id="relation-form" class="module author-form"><p>Attach an explicitly proposed or unresolved door to another registered object. A source coordinate records ancestry; it does not verify the relationship.</p><label>Destination<select name="target" required>${choices.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select></label><label>Relationship<input name="type" maxlength="160" required placeholder="could be a scene in…"></label><label>State<select name="status"><option value="proposed">Proposed</option><option value="fogged">Unresolved / fogged</option></select></label><label>Why / source coordinate<textarea name="why" maxlength="1600" placeholder="Your reason for proposing this relation; exact source if known…"></textarea></label><button class="action" type="submit">Add door ↗</button></form>`;}
function currentCapsule(){const n=node();const outgoing=allRelations().slice(0,32).map(r=>({type:r.type,status:r.status,why:r.why,source:r.source||'',destination:nodes()[r.to]?{name:nodes()[r.to].name,address:nodes()[r.to].address,source:nodes()[r.to].source}:null}));
 const drafts=Object.fromEntries(Object.entries(state.drafts).filter(([k])=>k.startsWith(n.id+':')).slice(0,12).map(([k,v])=>[k.slice(n.id.length+1),String(v).slice(0,6000)]));
 const questions=Object.fromEntries(Object.entries(state.questions).filter(([k])=>k.startsWith(n.id+':')).slice(0,24));
 return {format:'static-room-context-capsule',version:2,createdAt:stamp(),boundary:'A bounded local projection, not the full field; demo seeds and locally authored claims are not independently verified.',object:{id:n.id,name:n.name,kind:n.kind,address:n.address,summary:n.summary,source:n.source},sourceEvidence:boundedSourceEvidence(n),brief:state.briefs[n.id]||'',intent:state.intent,instruments:activeModules(),request:state.notes['last-request']||'',drafts,doors:outgoing,questions,receipts:state.records.filter(r=>r.object===n.id).slice(0,12)};
}
function capsuleMarkdown(){const c=currentCapsule();return `# STATIC ROOM · Context capsule\n\nObject: ${c.object.name} (${c.object.address})\nKind: ${c.object.kind}\nSource: ${c.object.source}\nIntent: ${c.intent}\nMounted instruments: ${c.instruments.join(', ')}\nLast request: ${c.request}\n\n## Source evidence (frozen excerpt or locally imported file)\n${c.sourceEvidence?JSON.stringify(c.sourceEvidence,null,2):'(No source attached; object may be a demonstration seed.)'}\n\n## Creative brief\n${c.brief||'(none)'}\n\n## Working material\n${Object.entries(c.drafts).map(([k,v])=>`### ${k}\n${v}`).join('\n\n')||'(none)'}\n\n## Nearby doors\n${c.doors.map(d=>`- ${d.type} -> ${d.destination?.address||'missing'} [${d.status}] | ${d.why}`).join('\n')||'(none)'}\n\n## Open questions\n${Object.values(c.questions).join('\n')||'(none)'}\n\n## Boundary\n${c.boundary}\n`}
function capsuleMarkup(){const c=currentCapsule();return `<section class="hero"><div><span class="eyebrow">RECEIVE / HOLD / POUR</span><h1>Context capsule</h1><p>A bounded, inspectable packet for re-entry or carrying into ChatGPT. The full field stays outside this packet.</p></div></section><section class="workspace"><h3>${esc(c.object.name)}</h3><p class="subtle">${esc(c.object.address)} · ${esc(c.object.source)}</p><div class="module-actions"><button class="action" id="capsule-md">Export capsule .md ↗</button><button class="action secondary" id="capsule-json">Export capsule .json ↗</button><button class="action secondary" id="capsule-copy">Copy text</button><button class="action secondary" data-viewgo="room">Back to Room</button></div><p class="subtle">Copy this text into a chat, or export the current neighborhood. Nothing is automatically sent to an AI service.</p><label class="sr" for="capsule-text">Portable context text</label><textarea id="capsule-text" readonly rows="20" class="capsule-text">${esc(capsuleMarkdown())}</textarea><details class="rack"><summary>Inspect the structured packet</summary><pre class="json-preview">${esc(JSON.stringify(c,null,2))}</pre></details></section>`;}
function historyMarkup(){return `<div class="row"><div><span class="eyebrow">LAWFUL RE-ENTRY</span><h2 class="heading" style="margin-top:7px">Saved encounters</h2></div><button class="action" id="capture">Capture current ↗</button></div><p class="subtle">Capture creates a local point of re-entry and a receipt. Re-entry does not overwrite newer working drafts; download the historical encounter to inspect its captured material.</p>${state.encounters.length?state.encounters.map(e=>`<article class="workspace" style="margin:10px 0"><div class="row"><span class="eyebrow">SESSION ${esc(e.id)} · ${esc(new Date(e.at).toLocaleString())}</span><span class="tag">${esc(INTENTS[e.intent]?.label||e.intent)}</span></div><h3>${esc(e.name)}</h3><p class="subtle">${esc(e.address)} · ${esc(e.note||'No encounter note recorded.')}</p><div class="module-actions" style="display:flex;gap:8px;margin-top:14px"><button class="action secondary small" data-reenter="${esc(e.id)}">Re-enter ↗</button><button class="action secondary small" data-export-encounter="${esc(e.id)}">Export note ↗</button></div></article>`).join(''):'<p class="empty">No encounters captured yet. Make a small note, then capture your current Room.</p>'}`;}
function receiptMarkup(){return `<div class="row"><div><span class="eyebrow">ATTRIBUTABLE LOCAL HISTORY</span><h2 class="heading" style="margin-top:7px">Projection & encounter receipts</h2></div><button class="action secondary small" id="export-json">Export snapshot ↗</button></div><p class="subtle">Receipts document user actions and deterministic local projections. They do not verify the underlying demo content or establish external authority.</p>${state.records.map(r=>`<div class="receipt"><strong>#${esc(r.id)} · ${esc(r.type)}</strong> · ${esc(new Date(r.at).toLocaleString())}<br>${esc(r.detail)}<br><small>${esc(r.address)}</small></div>`).join('')||'<p class="empty">No receipts yet. Open an object or compose an intent to begin a local trace.</p>'}`;}
function inspectorMarkup(){const n=node();const rr=allRelations();return `<div class="inspector-head"><span class="eyebrow">THE FIELD / LIVE INSPECTOR</span><h3>What remains here</h3><p class="subtle">${esc(state.sessionName)}<br>${esc(n.address)}</p></div><section class="panel"><h4>FogGlass <span style="float:right;color:var(--fog)">${state.fog?'ACTIVE':'HIDDEN'}</span></h4><div class="mini"><b>Known locally</b><p>${esc(n.kind)} object is registered in this demonstration field.</p><div class="meter"><i style="width:100%;background:var(--mint)"></i></div></div><div class="mini"><b>Proposed connections</b><p>${rr.filter(r=>r.status==='proposed').length} working edges. Association is not proof or approval.</p><div class="meter"><i style="width:${Math.min(100,rr.filter(r=>r.status==='proposed').length*25)}%;background:var(--gold)"></i></div></div><div class="mini"><b>Unresolved doors</b><p>${rr.filter(r=>r.status==='fogged').length} edges require additional evidence or an import.</p><div class="meter"><i style="width:${Math.min(100,rr.filter(r=>r.status==='fogged').length*25)}%"></i></div></div><button class="action secondary" id="toggle-fog">${state.fog?'Hide':'Show'} fog annotations</button></section><section class="panel"><h4>Projection anatomy</h4><div class="mini"><b>RECEIVE</b><p>${esc(state.notes['last-request']||'Current object and explicitly selected intent')}</p></div><div class="mini"><b>HOLD</b><p>${state.visited.length} visited objects · ${state.encounters.length} saved encounters · ${state.records.length} local receipts</p></div><div class="mini"><b>POUR</b><p>${esc(activeModules().join(' + '))}</p></div></section><section class="panel"><h4>Source boundary</h4><p class="subtle">${esc(n.source)}. No external repository or file has been verified by this page.</p><button class="action secondary" id="open-capsule">Carry context capsule ↗</button><button class="action secondary" id="export-json">Export complete snapshot ↗</button><button class="action secondary" id="import-json">Import snapshot ↘</button><input type="file" id="import-file" accept=".json,application/json" class="hidden"><button class="action secondary" id="reset">Start fresh demo</button></section><section class="panel"><h4>Next experiment</h4><p class="subtle">Write a beat, save a local trace, capture this encounter, navigate to a neighboring object, then re-enter the saved encounter. Watch the working surface change without losing the field.</p>${!storageOK?'<div class="notification">Local storage is unavailable. Export snapshots manually before closing.</div>':''}</section>`;}

function sourceProof(n){return BUNDLED_SOURCE_PROOFS[n.id]||state.sourceFiles[n.id]||null;}
function boundedSourceEvidence(n){const p=sourceProof(n);if(!p)return null;
 if(BUNDLED_SOURCE_PROOFS[n.id])return {tier:'bundled-frozen-GitHub-witness-not-live-verified',repository:p.repository,commit:p.commit,path:p.path,blobSha:p.blobSha,checkedAt:p.checkedAt,url:p.url,lineStart:p.lineStart,excerpt:p.excerpt};
 return {tier:'user-imported-file-not-externally-verified',name:p.name,importedAt:p.importedAt,excerpt:p.excerpt,contentTruncated:p.contentTruncated};}
function sourceReaderMarkup(n){const p=sourceProof(n);if(!p)return `<div class="module"><h4>Source reader</h4><p>No source content attached. Visit Source shelf to inspect pinned excerpts or import a local text file.</p><div class="module-actions"><button class="action secondary small" data-viewgo="sources">Open source shelf ↗</button></div></div>`;
 const bundled=!!BUNDLED_SOURCE_PROOFS[n.id];return `<div class="module source-module"><h4>Source reader · ${bundled?'frozen repository witness':'local file'}</h4><p>${bundled?`${esc(p.repository)} · ${esc(p.path)} · ${esc(p.commit.slice(0,12))}`:`${esc(p.name)} · imported locally, not externally verified`}</p><pre class="source-preview">${esc(p.excerpt)}</pre>${bundled?`<p>Bundled excerpt from a source inspected on ${esc(p.checkedAt)}. This Room cannot check whether the upstream branch has changed. <a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open pinned source ↗</a></p>`:`<p>Local file text is data only; the Room has not verified its source.</p>`}<div class="module-actions"><button class="action secondary small" id="source-excerpt">Inspect source excerpt ↗</button><button class="action secondary small" id="source-brief">Compose brief from source ↗</button><button class="action secondary small" id="source-handoff">Export source handoff ↗</button></div></div>`;}
function handoffModuleMarkup(n){return `<div class="module"><h4>Project handoff</h4><p>Carry the selected creative object, bounded source evidence, draft and separate local brief into ChatGPT or a project review. Download only; no external service is called.</p><div class="module-actions"><button class="action secondary small" id="source-handoff">Export source handoff ↗</button><button class="action secondary small" id="open-capsule">Inspect context ↗</button></div>${state.briefs[n.id]?`<pre class="source-preview">${esc(state.briefs[n.id])}</pre>`:''}</div>`;}
function sourceQuickMarkup(){const p=sourceProof(node());return `<div class="source-quick"><span>${p?(BUNDLED_SOURCE_PROOFS[node().id]?'PINNED SOURCE EXCERPT':'IMPORTED LOCAL TEXT'):'NO ATTACHED SOURCE'}</span><button class="action secondary small" data-viewgo="sources">Source shelf ↗</button>${p?`<button class="action secondary small" id="source-brief">Compose source brief ↗</button>`:''}</div>`;}
function sourcesMarkup(){const ids=Object.values(nodes()).filter(n=>sourceProof(n));return `<section class="hero"><div><span class="eyebrow">SOURCES / RECEIPTS / CAPABILITY</span><h1>Source shelf</h1><p>A bounded reading desk for frozen project witnesses and imported local text. Source identity stays separate from local creative work.</p></div></section><section class="workspace"><h3>Bring in a source</h3><p class="subtle">Import a .md or .txt file (max 64 KB); content stays local and is never executed or presented as externally verified. This does not connect to your private GitHub repos.</p><div class="module-actions"><button class="action" id="source-import">Import local text ↘</button><button class="action secondary" id="source-handoff">Export current handoff ↗</button></div><input id="source-file" class="hidden" type="file" accept=".md,.txt,text/plain,text/markdown"><h3>Available witnesses</h3><div class="doorlist">${ids.map(n=>{const p=sourceProof(n);return `<button class="door" data-go="${esc(n.id)}"><span class="glyph">${esc(n.glyph)}</span><span style="flex:1"><strong>${esc(n.name)}</strong><small>${BUNDLED_SOURCE_PROOFS[n.id]?'Bundled · pinned GitHub source · offline excerpt':p.tier==='workbench-local-inspected-once'?'Workbench · dated read-only local inspection':'User-imported · unverified local file'}<br>${esc(p.repository||p.name||'')} ${p.commit?'@ '+esc(p.commit.slice(0,12)):p.head?'@ '+esc(p.head):''}</small></span></button>`;}).join('')}</div></section><section class="workspace"><h3>Local capability registry</h3><p class="subtle">This Room has only these three explicit, deterministic operations. A descriptor never grants remote project execution.</p>${Object.entries(CAPABILITIES).map(([key,c])=>`<div class="mini"><b>${esc(key)} · ${esc(c.label)}</b><p>Effect: ${esc(c.effects.join(', '))} · Consent: ${esc(c.permission)} · External effects: none</p></div>`).join('')}</section>`;}
function sourceBrief(n,p){const s=p.excerpt.slice(0,6500),coordinate=BUNDLED_SOURCE_PROOFS[n.id]?`${p.repository}@${p.commit} / ${p.path} · excerpt from line ${p.lineStart}`:`Local file ${p.name}; source NOT independently verified`;
 return `STATIC ROOM 003 · Source-grounded creative brief\nSource: ${coordinate}\nObject: ${n.address}\nIntent: ${INTENTS[state.intent].label}\n\nREAD (quoted source excerpt):\n${s}\n\nPROPOSE (human-authored creative work):\nWhat could this source make possible in the current encounter?\n\nVERIFY / FOG:\nWhich source facts, capabilities, and relationships still require project-owned confirmation?\n\nNEXT LOCAL ACTION:\nWrite a draft or grow a proposed child object; do not treat this brief as project authority.`;}
function runCapability(op){const n=node(),p=sourceProof(n);if(!CAPABILITIES[op])return;
 if(op!=='handoff.export'&&!p){notice('Choose a source with content from Source shelf first.');return;}
 if(op==='source.excerpt'){record('capability · read','Opened bounded source excerpt; no network access or source mutation.');persist();state.view='room';render();notice('Source excerpt available in projected desk.');return;}
 if(op==='brief.compose'){const brief=sourceBrief(n,p);state.briefs[n.id]=brief;record('capability · compose','Created separate local source-grounded brief; original source and prior drafts unchanged.');persist();state.view='room';render();notice('Local brief composed without changing the source.');return;}
 const h={format:'static-room-source-handoff',version:1,createdAt:stamp(),boundary:'Local export for human review. Neither source presence nor proposed composition authorizes project execution, commits, or publication.',object:{id:n.id,name:n.name,address:n.address,kind:n.kind},intent:state.intent,sourceEvidence:boundedSourceEvidence(n),brief:state.briefs[n.id]||'',drafts:Object.fromEntries(Object.entries(state.drafts).filter(([k])=>k.startsWith(n.id+':')).slice(0,10).map(([k,v])=>[k.slice(n.id.length+1),String(v).slice(0,6000)])),questions:Object.values(state.questions).slice(0,12),localReceiptCount:state.records.length};
 record('capability · handoff',`Prepared bounded export from ${n.address}; no external destination called.`);persist();exportFile(`static-room-003-handoff-${n.id}.json`,JSON.stringify(h,null,2),'application/json');notice('Handoff downloaded. Review before sending anywhere.');}
function importSourceFile(file){if(!file)return;const ext=file.name.toLowerCase();if(!/\.(md|txt)$/.test(ext)||file.size>65536||file.size===0){notice('Choose a .md or .txt file between 1 byte and 64 KB.');return;}
 const reader=new FileReader();reader.onload=()=>{const body=String(reader.result||'');if(!body.trim()||body.includes('\0')){notice('The text file is empty or contains binary data.');return;}
 if(Object.keys(state.customNodes).length>=200){notice('Local object limit reached.');return;}
 const serial=id(),key='file-'+serial,clean=file.name.slice(0,120),p={name:clean,importedAt:stamp(),excerpt:body.slice(0,12000),contentTruncated:body.length>12000};
 state.customNodes[key]={id:key,name:clean,kind:'Local source',glyph:'▤',address:`static://source/local/${serial}`,summary:'Imported local text; not externally verified or executed.',source:'User-imported local text · no external verification',relations:[]};state.sourceFiles[key]=p;record('source import',`Imported local text ${clean} (${file.size} bytes); content bounded and unverified.`);go(key);notice('Local source imported. Original file is unchanged.');};reader.onerror=()=>notice('Could not read this file.');reader.readAsText(file);}

function render(){document.getElementById('address').value=state.view==='room'?node().address:`static://room/${state.view}`;document.getElementById('back').disabled=state.stackIndex<=0;document.getElementById('forward').disabled=state.stackIndex>=state.stack.length-1;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));document.getElementById('node-nav').innerHTML=Object.values(nodes()).map(n=>`<button class="node-btn ${n.id===state.current?'active':''}" data-go="${esc(n.id)}"><span class="symbol">${esc(n.glyph)}</span><span class="node-copy"><strong>${esc(n.name)}</strong><small>${esc(n.kind)}</small></span></button>`).join('');document.getElementById('screen').innerHTML=state.view==='room'?roomMarkup():state.view==='field'?fieldMarkup():state.view==='history'?historyMarkup():state.view==='receipt'?receiptMarkup():state.view==='forge'?forgeMarkup():state.view==='capsule'?capsuleMarkup():sourcesMarkup();document.getElementById('inspector').innerHTML=inspectorMarkup();}
function saveDraft(type){const el=document.querySelector(`[data-draft="${type}"]`);if(el)state.drafts[`${state.current}:${type}`]=el.value;record('working note',`Saved ${type} draft for ${node().name}; draft remains user-authored and local.`);persist();notice('Working note saved locally.');}
function capture(){const n=node();const note=(state.drafts[`${n.id}:trace`]||state.drafts[`${n.id}:${INTENTS[state.intent].modules[0]}`]||'').slice(0,350);const e={id:id(),at:stamp(),object:state.current,address:n.address,intent:state.intent,name:n.name,note,source:n.source,drafts:clone(Object.fromEntries(Object.entries(state.drafts).filter(([k])=>k.startsWith(n.id+':'))))};state.encounters.unshift(e);record('encounter',`Captured local encounter #${e.id}: ${e.address} / ${INTENTS[e.intent].label}`);persist();render();notice(`Encounter ${e.id} captured. Open Encounters to re-enter.`);}
function exportFile(filename,content,mime){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function markdown(type){const n=node();return `# ${n.name} — ${type}\n\nAddress: ${n.address}\nSource status: ${n.source}\nCreated: ${stamp()}\nIntent: ${INTENTS[state.intent].label}\n\n## Working material\n\n${state.drafts[`${n.id}:${type}`]||'(blank)'}\n\n## Boundary\n\nLocally authored working material. No source validation or external publication has occurred.\n`;}
function snapshot(){return {format:'static-room-snapshot',exportedAt:stamp(),state:clone(state)};}
function importSnapshot(file){if(!file)return;if(file.size>2200000){notice('Snapshot too large for this local Room (2.2 MB limit).');return;}
 const rd=new FileReader();rd.onload=()=>{try{
  const x=JSON.parse(rd.result);if(x.format!=='static-room-snapshot'||!x.state)throw Error('Not a compatible Room snapshot');
  const next=normalizeState(x.state);state=next;record('import','Imported Room 001/002/003 compatible local snapshot.');persist();render();notice('Room snapshot imported.');
 }catch(err){notice(`Import rejected: ${err.message}`);}};rd.readAsText(file);
}
function createObject(form){const data=new FormData(form);const name=String(data.get('name')||'').trim(),kind=String(data.get('kind')||'Idea').trim();if(!name||name.length>120||!KINDS.includes(kind)){notice('Enter a valid name and kind.');return;}
 const seed=state.forgeSeed||{};const parent=nodes()[seed.from||state.current];const serial=id();const key='leaf-'+serial;const slug=name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'untitled';
 const summary=String(data.get('summary')||'').trim().slice(0,2000);const supplied=String(data.get('source')||'').trim().slice(0,1000);
 const obj={id:key,name,kind,glyph:'✧',address:`static://local/${slug}-${serial}`,summary:summary||'Locally authored creative object.',source:`Local authorship · ${supplied||'Room encounter '+parent.address}`,relations:[]};
 state.customNodes[key]=obj;
 const label=String(data.get('relation')||'inspired a new local object').trim().slice(0,160)||'inspired a new local object';
 (state.extraRelations[parent.id]??=[]).push({to:key,type:label,status:'proposed',why:'Explicitly created in Room 002; locally authored proposal, not external canon.',source:supplied||parent.address});
 obj.relations.push({to:parent.id,type:'grew from',status:'proposed',why:'Local creation ancestry, not an externally verified historical claim.',source:parent.address});
 if(seed.content){const target={scene:'scene',music:'music',story:'story',world:'world',research:'questions',explore:'trace'}[seed.intent]||'trace';state.drafts[`${key}:${target}`]=String(seed.content).slice(0,25000);}
 state.forgeSeed=null;record('object birth',`Created ${obj.address} from ${parent.address} with proposed door: ${label}`);go(key);notice('New object created with its own address and explicit ancestry.');
}
function addRelation(form){const data=new FormData(form);const to=String(data.get('target')||''),type=String(data.get('type')||'').trim().slice(0,160),status=String(data.get('status')||'proposed');
 if(!nodes()[to]||to===state.current||!type||!['proposed','fogged'].includes(status)){notice('Choose another object, a relationship, and a permitted state.');return;}
 const why=String(data.get('why')||'').trim().slice(0,1600);(state.extraRelations[state.current]??=[]).push({to,type,status,why:why||'Locally proposed relationship. No source verified.',source:why});
 record('relationship birth',`Created ${status} door: ${node().address} -> ${nodes()[to].address}, type ${type}`);persist();render();notice(`${status} door added; no external fact was verified.`);
}
document.addEventListener('submit',e=>{if(e.target.id==='forge-form'){e.preventDefault();createObject(e.target);}if(e.target.id==='relation-form'){e.preventDefault();addRelation(e.target);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-draft]')){state.drafts[`${state.current}:${e.target.dataset.draft}`]=e.target.value;persist();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;persist();render();return;}if(b.dataset.viewgo){state.view=b.dataset.viewgo;persist();render();return;}if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.intent){setIntent(b.dataset.intent);return;}if(b.dataset.save){saveDraft(b.dataset.save);return;}if(b.dataset.exportMd){exportFile(`static-room-${node().id}-${b.dataset.exportMd}.md`,markdown(b.dataset.exportMd),'text/markdown');return;}if(b.dataset.question){const key=b.dataset.question;const r=allRelations().find(r=>r.key===key);state.questions[key]=`What evidence would establish “${r?.type||'this relation'}” from ${node().name} to ${nodes()[r?.to]?.name||'the destination'}? ${r?.why||''}`;record('question',`Created research question for ${key}`);persist();render();notice('Unresolved research question recorded.');return;}if(b.dataset.reenter){const en=state.encounters.find(x=>x.id===b.dataset.reenter);if(en){go(en.object);setIntent(en.intent,`saved encounter #${en.id}`);record('re-entry',`Re-entered encounter #${en.id}; preserved current drafts and historical captured drafts separately.`);persist();render();}return;}if(b.dataset.exportEncounter){const en=state.encounters.find(x=>x.id===b.dataset.exportEncounter);if(en)exportFile(`static-room-encounter-${en.id}.md`,`# ${en.name}\n\nAddress: ${en.address}\nCaptured: ${en.at}\nIntent: ${INTENTS[en.intent]?.label||en.intent}\nSource: ${en.source}\n\n${en.note||''}\n\n## Drafts\n\n${Object.entries(en.drafts||{}).map(([k,v])=>`### ${k}\n${v}`).join('\n\n')}\n\nLocal draft; not independently verified.\n`,'text/markdown');return;}
 switch(b.id){case 'new-object':state.forgeSeed={from:state.current};state.view='forge';persist();render();break;case 'grow-draft':{const m=activeModules().find(x=>state.drafts[`${state.current}:${x}`]?.trim());state.forgeSeed={from:state.current,kind:state.intent==='scene'?'Scene':state.intent==='world'?'World':state.intent==='music'?'Song':'Idea',name:'New '+(state.intent==='scene'?'scene':state.intent==='world'?'world':state.intent==='music'?'song':'idea'),content:m?state.drafts[`${state.current}:${m}`]:'',intent:state.intent,relation:'grew into'};state.view='forge';persist();render();break;}case 'cancel-forge':state.forgeSeed=null;state.view='room';persist();render();break;case 'open-capsule':state.view='capsule';persist();render();break;case 'capsule-md':exportFile(`static-room-capsule-${node().id}.md`,capsuleMarkdown(),'text/markdown');break;case 'capsule-json':exportFile(`static-room-capsule-${node().id}.json`,JSON.stringify(currentCapsule(),null,2),'application/json');break;case 'capsule-copy':{const txt=document.getElementById('capsule-text');txt.select();if(navigator.clipboard?.writeText){navigator.clipboard.writeText(txt.value).then(()=>notice('Context capsule copied.')).catch(()=>notice('Select the text and copy it manually.'));}else notice('Text selected. Copy it manually.');break;}case 'back':if(state.stackIndex>0){state.stackIndex--;go(state.stack[state.stackIndex],false);}break;case 'forward':if(state.stackIndex<state.stack.length-1){state.stackIndex++;go(state.stack[state.stackIndex],false);}break;case 'capture':capture();break;case 'toggle-fog':state.fog=!state.fog;persist();render();break;case 'export-json':exportFile('static-room-003-snapshot.json',JSON.stringify(snapshot(),null,2),'application/json');break;case 'import-json':document.getElementById('import-file').click();break;case 'source-import':document.getElementById('source-file').click();break;case 'source-excerpt':runCapability('source.excerpt');break;case 'source-brief':runCapability('brief.compose');break;case 'source-handoff':runCapability('handoff.export');break;case 'reset':if(confirm('Reset all local Room notes, drafts, receipts, and encounters? Export a snapshot first if needed.')){state=defaultState();persist();render();notice('Started a fresh demonstration field.');}break;}
});
document.getElementById('address-form').addEventListener('submit',e=>{e.preventDefault();routeAddress(document.getElementById('address').value);});
document.getElementById('command-form').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('command');const q=input.value.trim();if(q){compose(q);input.value='';}});
document.addEventListener('change',e=>{if(e.target.matches('[data-module-control]')){const key=state.current+'|'+state.intent;const next=MODULES.filter(m=>{const c=document.querySelector(`[data-module-control="${m}"]`);return c?.checked;});if(!next.length){e.target.checked=true;notice('A projection needs at least one instrument.');return;}state.modulePicks[key]=next;record('instrument composition',`Mounted ${next.join(', ')} for ${key}`);persist();render();return;}if(e.target.id==='import-file'){importSnapshot(e.target.files?.[0]);e.target.value='';}if(e.target.id==='source-file'){importSourceFile(e.target.files?.[0]);e.target.value='';}});
render();
